int main() {
    std::mutex mutex; std::condition_variable ready; std::queue<int> tasks; bool done = false;
    std::jthread consumer([&] {
        std::unique_lock lock(mutex);
        ready.wait(lock, [&] { return done || !tasks.empty(); });
        while (!tasks.empty()) { std::cout << tasks.front() << '\n'; tasks.pop(); }
    });
    { std::lock_guard lock(mutex); tasks.push(10); tasks.push(20); done = true; }
